// Generates cli/lib/src/review/references.g.dart: the pre-ship review brief and
// findings schema of skills/specwright-review/references/ as Dart constants, so
// `sw review` needs no skill folder on disk (design D9).
//   dart run cli/tool/references.dart
// cli/tool/build.dart runs the same generation before it compiles, and
// cli/test/review/references_test.dart fails when the committed file differs
// from the sources.
import 'dart:io';

const String _header = '''
// GENERATED by cli/tool/references.dart from
// skills/specwright-review/references/. Do not edit: change the sources and run
// `mise run references`.

''';

/// The text of `references.g.dart` for the two sources.
String renderReferences({required String brief, required String schema}) =>
    '$_header'
    '/// The pre-ship review brief, built in.\n'
    '///\n'
    '/// C4: The built-in brief and schema must equal\n'
    '/// `skills/specwright-review/references/`; the drift test guards it.\n'
    "const String reviewBrief = ${_literal(brief)};\n"
    '\n'
    '/// The findings schema a reviewer route is given as a file; `sw review` '
    'writes\n'
    '/// it into the run directory.\n'
    'const String findingsSchema = ${_literal(schema)};\n';

/// [text] as a raw multi-line string literal. The sources hold no `'''` and
/// start with no newline, which the literal would swallow.
String _literal(String text) {
  if (text.contains("'''") || text.startsWith('\n')) {
    throw StateError('a reference file cannot be a raw multi-line literal');
  }
  return "r'''$text'''";
}

/// A reference file with LF line ends, as git stores it.
String readReference(Directory tree, String name) =>
    File('${tree.path}/skills/specwright-review/references/$name')
        .readAsStringSync()
        .replaceAll('\r\n', '\n');

/// Writes `references.g.dart` under the checkout at [tree].
void writeReferences(Directory tree) {
  final text = renderReferences(
    brief: readReference(tree, 'brief.md'),
    schema: readReference(tree, 'findings.schema.json'),
  );
  File('${tree.path}/cli/lib/src/review/references.g.dart')
    ..createSync(recursive: true)
    ..writeAsStringSync(text);
}

void main() {
  // cli/tool/references.dart: the checkout is two directories up.
  writeReferences(File.fromUri(Platform.script).parent.parent.parent);
}
